def internals(source: str, source_path: StrPath | None = None, input_encoding: Literal['unicode'] | str = 'unicode', settings_overrides: dict[(str, Any)] | None = None) -> tuple[(nodes.document, Publisher)]:
    """
    Return the document tree and publisher, for exploring Docutils internals.

    Parameters: see `html_parts()`.
    """
    if settings_overrides is None:
        settings_overrides = {}
    overrides = settings_overrides | {'input_encoding': input_encoding}
    publisher = core.Publisher('standalone', 'rst', 'null', source_class=io.StringInput, destination_class=io.NullOutput)
    publisher.process_programmatic_settings(settings_spec=None, settings_overrides=overrides, config_section=None)
    publisher.set_source(source, source_path)
    publisher.publish()
    return (publisher.document, publisher)

